			function getUnitSystemRegionInst(){
			    
			    /* 시도, 시군구, 기관 목록 조회 */
			    var dmListParam = app.lookup("dmListParam");
			    dmListParam.clear();
			    dmListParam.setValue("unitTaskWork", untTaskwk);    /* 단위시스템*/
			    
			    util.Submit.send(app, "subUnitSystemOrganization", function(pbSuccess) {
			        if (pbSuccess) {
			            
			            var dsOrganization = app.lookup("dsOrganization");
			            dsOrganization.clearFilter();
			            
			            var dsOrgRegionSido = app.lookup("dsOrgRegionSido");
			            var dsOrgRegionSgg = app.lookup("dsOrgRegionSgg");
			            var dsOrgRegion = app.lookup("dsOrgRegion");
			            
			            dsOrgRegionSido.clear();
			            dsOrgRegionSgg.clear();
			            
			            var rowDatas = dsOrgRegion.getRowDataRanged();
			            var arrTmp = new Array();
			            for (var i = 0; i < rowDatas.length; i++) {
			                if (arrTmp.indexOf(rowDatas[i]["ENG_CTPV_NM"]) == -1) {
			                    var newRowData = {
			                        "CTPV_NM": rowDatas[i]["CTPV_NM"],
			                        "ENG_CTPV_NM": rowDatas[i]["ENG_CTPV_NM"],
			                        "SGG_CD": rowDatas[i]["SGG_CD"].substring(0, 2)
			                    };
			                    dsOrgRegionSido.pushRowData(newRowData);
			                    dsOrgRegionSido.commit();
			                    arrTmp.push(rowDatas[i]["ENG_CTPV_NM"]);
			                }
			                
			                
			                if (arrTmp.indexOf(rowDatas[i]["SGG_CD"]) == -1){
			                    var newRowData1 = {
			                        "SGG_CD": rowDatas[i]["SGG_CD"],
			                        "ENG_CTPV_NM": rowDatas[i]["ENG_CTPV_NM"],                        
			                        "SGG_NM": (rowDatas[i]["SGG_NM"] == "*" ? "세종특별자치시": rowDatas[i]["SGG_NM"])
			                    };
			                    dsOrgRegionSgg.pushRowData(newRowData1);
			                    dsOrgRegionSgg.commit();
			                    arrTmp.push(rowDatas[i]["SGG_CD"]);
			                }                
			            }
			            
			            var instNmCondition = '';
			            if(untTaskwk == 'U01'){
			                /* 2023-02-16 YOO.CHI.HOON filter 추가 전용가입라디오 단위들 제거*/
			                instNmCondition = '(getValue("INST_NM") != "여성가족부") && (getValue("INST_NM") != "한국청소년상담복지개발원") && (getValue("INST_NM").indexOf("경찰청") < 0 ) && (getValue("INST_NM").indexOf("경찰서") < 0 )';
			                dsOrganization.setFilter(instNmCondition);
			            }else if(untTaskwk == 'U03'){
			                instNmCondition = '(getValue("INST_NM").indexOf("교육부") < 0 ) && (getValue("INST_NM").indexOf("교육청") < 0 )';
			                dsOrganization.setFilter(instNmCondition);
			            }
			            
			        }
			    });
			    util.Control.redraw(app, "grp1");
			    util.Control.redraw(app, "grpFltBtns");
			}

