			    var grdSsgCd = grdList.getRow(grdRowIdx).getRowData().CNTER_SGG_CD;
			    
			    var tmp1  = "";
			    var tmp2  = "";
			    
			    for (var i = 0; i <= dsOrgSido.getRowCount(); i++){
			            var engCtpv = dsOrgSido.getValue(i, "ENG_CTPV_NM");
			            var ctSsg     = dsOrgSido.getValue(i, "SGG_CD");
			        
			            if(grdCtCd == ctSsg){
			                tmp1 = engCtpv;
			                    if(grdSsgCd != '' && grdSsgCd != null){
			                        tmp2 = grdSsgCd;
			                    }
			                }
			        }
			    
